Let $R, S, N \ge 1/2$, $M_1, M_2, C, Z \gg 1$, $M \asymp M_1 M_2$, and $Y, \varepsilon > 0$. For all $r \sim R$, $s \sim S$ with $(r, s) = 1$, let:
\begin{itemize} 
    \item $w_{r,s} \in \mathbb{C}$; 
    \item $\Phi_{r,s} : (0, \infty)^4 \to \mathbb{C}$ be smooth, with $\Phi_{r,s}(x_1, x_2, y, z)$ supported in $x_1, x_2, y, z \asymp 1$, and
    \[ 
        \partial_{x_1}^{j_1} \partial_{x_2}^{j_2} \partial_y^k \partial_z^\ell \Phi_q(x_1, x_2, y, z) \ll_{j_1,j_2,k,\ell,\varepsilon} Z^{(j_1+j_2+k)\varepsilon},
        \qquad 
        \forall j_1, j_2, k, \ell \ge 0;
    \]
    \item $(rs, N, Z, (a_{n,r,s})_{n \sim N}, A_{r,s}, Y)$ be a tuple satisfying 3.2.
\end{itemize} 
Then with a consistent choice of the sign $\pm$, it holds that
\begin{equation} 
\begin{aligned}
    \sum_{\substack{r \sim R \\ s \sim S \\ (r, s) = 1}} w_{r,s} \sum_{m_1, m_2 \in \mathbb{Z}} 
    \sum_{n \sim N} a_{n,r,s}
    \sum_{(c, r) = 1} \Phi_{r,s}\left(\frac{m_1}{M_1}, \frac{m_2}{M_2}, \frac{n}{N}, \frac{c}{C}\right) S(m_1m_2\overline{r}, \pm n; sc)
    \ll_\varepsilon
    (RSMNCZ)^{O(\varepsilon)}
    \\
    \times 
    \left(1 + \frac{C \sqrt{M_1}}{R \sqrt{SY}}\right)^{\theta_{\max}} 
    \|w_{r,s} A_{r,s}\|_2 \sqrt{RSM}
    \left(\frac{C^2}{R} (M + RS)(N + RS) + MN \right)^{1/2}.
\end{aligned}
\end{equation}

Let $R, S, N \ge 1/2$, $C, D, Z \gg 1$, and $Y, \varepsilon > 0$. For all $r \sim R$, $s \sim S$ with $(r, s) = 1$, let:
\begin{itemize} 
    \item $w_{r,s} \in \mathbb{C}$; 
    \item $\Phi_{r,s} : (0, \infty)^3 \to \mathbb{C}$ be smooth, with $\Phi_{r,s}(x, y, z)$ supported in $x, y, z \asymp 1$, and
    \[ 
        \partial_x^j \partial_y^k \partial_z^\ell \Phi_q(x, y, z) \ll_{j,k,\ell,\varepsilon} Z^{j\varepsilon},
        \qquad 
        \forall j, k, \ell \ge 0;
    \]
    \item $(rs, N, Z, (a_{n,r,s})_{n \sim N}, A_{r,s}, Y)$ be a tuple satisfying 3.2.
\end{itemize} 
Then with a consistent choice of the sign $\pm$, it holds that
\begin{equation} 
    \sum_{\substack{r \sim R \\ s \sim S \\ (r, s) = 1}} w_{r,s}
    \sum_{n \sim N} a_{n,r,s}
    \sum_{\substack{c, d \\ (rd, sc) = 1}} \Phi_{r,s}\left(\frac{n}{N}, \frac{d}{D}, \frac{c}{C}\right) e\left(\pm n \frac{\overline{rd}}{sc}\right)
    \ll_\varepsilon 
    (RSNCDZ)^{O(\varepsilon)}\, \|w_{r,s} A_{r,s}\|_2 \mathscr{I},
\end{equation}
where
\[
    \mathscr{I}^2 := D^2 NR
    +
    \left(1 + \frac{C^2}{R^2 S Y}\right)^{\theta_{\max}} 
    CS(C + DR)(RS + N).
\]

Let $\varepsilon > 0$, $a \in \mathbb{Z} \setminus \{0\}$, $1 \ll S, F, K, C, H \ll x^{O(1)}$, $\Phi_i(t)$ be smooth functions supported in $t \asymp 1$ with $\Phi_i^{(j)} \ll_j 1$, and  
\[
    \phi(h_1, h_2) := \Phi_1\left(\frac{h_1}{H}\right) \Phi_2\left(\frac{h_2}{H}\right) e(h_1\alpha_1 + h_2\alpha_2),
\]
where $\alpha_i \in \mathbb{R}/\mathbb{Z}$ have $\min_i T_H(\alpha_i) \ll_\varepsilon x^\varepsilon$ (recall 3.1). Then for any smooth function $\Phi(x_1, x_2, z)$ supported in $x_i, z \asymp 1$, satisfying $\partial_{x_1}^{j_1} \partial_{x_2}^{j_2} \partial_z^\ell \Phi(x_1, x_2, z) \ll_{j_1, j_2, \ell, \varepsilon} x^{(j_1+j_2) \varepsilon}$, one has
\[
\begin{aligned}
    &\sum_{s_1, s_2 \sim S} \left\vert
    \sum_{f,k}
    \sum_{\substack{h_1, h_2 \\ \ell = h_1 s_1 - h_2 s_2 \neq 0}} \phi(h_1, h_2)
    \sum_{(c, s_1s_2) = 1}
    \Phi\left(\frac{f}{F}, \frac{k}{K}, \frac{c}{C}\right)
    S(fk\overline{s_1 s_2}, a\ell; c)
    \right\vert
    \\
    &\ll_{\varepsilon,a} x^{O(\varepsilon)}
    \left(1 + \frac{C\sqrt{F}}{S^2\sqrt{\frac{H^2}{H+S}}}\right)^{\theta_{\max}} 
    \sqrt{H^2S^3 (H + S) F K}
    \left(\frac{C^2}{S}\left(FK + S^2\right)\left(H + S\right) + FKHS\right)^{1/2}.
\end{aligned}
\]

Let $\varepsilon > 0$, $1 \ll N, T, H, K, L \ll x$ with $TH \ll N$, $a, d \in \mathbb{Z} \setminus \{0\}$ with $1 \le |a| \le x^\varepsilon$, $1 \le d \le x^{2\varepsilon}$, $\Phi_i(t)$ be smooth functions supported in $t \asymp 1$ with $\Phi_j^{(j)} \ll_j 1$, and 
\[
    \phi(h_1, h_2) := \Phi_1\left(\frac{h_1}{H}\right) \Phi_2\left(\frac{h_2}{H}\right) e(h_1\alpha_1 + h_2\alpha_2),
\]
where $\alpha_i \in \mathbb{R}/\mathbb{Z}$ have $\min_i T_H(\alpha_i) \ll x^{2\varepsilon}$ (recall 3.1). Then for any smooth function $\Phi(x_1, x_2, z)$ supported in $x_i, z \asymp 1$, satisfying $\partial_{x_1}^{j_1} \partial_{x_2}^{j_2} \partial_z^{\ell} \Phi(x_1, x_2, z) \ll_{j_1,j_2,\ell,\varepsilon} 1$, one has
\begin{equation} 
\begin{aligned}
    \sum_{n, n' \sim N}
    \left \vert
    \sum_{\substack{1 \le |t| \le T \\ (t, nn') = 1 \\ t \mid n - n'}} 
    \sum_{\substack{h, h' \\ e = at(n'h - nh') \neq 0}} \phi(h, h')
    \sum_{\substack{k, \ell \\ (k, dnn'\ell) = 1}}
    \Phi\left(\frac{\ell}{L}, \frac{k}{K}\right)
    e\left(\frac{e\overline{dnn'\ell}}{k}\right) \right \vert
    \\
    \ll_{\varepsilon} x^{6\varepsilon} THN 
    \left(L^2 TH N^3 + \left(1 + \frac{K^2}{N^3 TH^2}\right)^{\theta_{\max}} K \left(K + LN^2\right)N^2 \right)^{1/2}.
\end{aligned}
\end{equation}

Let $a \in \mathbb{Z} \setminus \{0\}$, $d \in \mathbb{Z}_+$ with $(a, d) = 1$, $\varepsilon, C > 0$, and $M, N, x, Q, R, S \gg 1$ satisfy $MN \asymp x$ and, with $\theta := 7/32$,
\begin{equation} 
\begin{aligned}
    N^2 R^2 S &\le x^{1-8\varepsilon}, 
    \\
    N^{\frac{2+\theta}{2-2\theta}} R S^{\frac{4-5\theta}{2-2\theta}}
    &\le 
    x^{1-16\varepsilon},
    \\ 
    N^{\frac{1+\theta}{1-\theta}} Q^{\frac{1-3\theta}{1-\theta}} R^{2} S^{5} &\le 
    x^{2-32\varepsilon}.
\end{aligned}
\end{equation}
Let $Q' \in [Q, 2Q]$, $1 \ll H \le x^{o(1)} Q R^2 S^2/M$, $B_i \gg 1$, and let $\mathscr{N} \subset \mathbb{Z}_+^2$ be such that if $(u; v), (u'; v') \in \mathscr{N}$, then $(u, v') = (u', v) = 1$. Finally, let $(\gamma_r)$, $(\lambda_s)$, $(\alpha_n)$ be $1$-bounded sequences, $\omega \in \mathbb{R}/\mathbb{Z}$ with $T_H(\omega) \ll x^{o(1)}$, and $\Phi(t)$ be a smooth function supported in $t \asymp 1$, with $\Phi^{(j)} \ll_j 1$ for $j \ge 0$. Then
\[
\begin{aligned}
    \sum_{\substack{Q \le q \le Q' \\ (q, a) = 1}}
    \sum_{r_1, r_2 \sim R}
    \sum_{\substack{s_1, s_2 \sim S \\ (r_1s_1, ar_2s_2) = 1 \\ (r_2 s_2, a q d r_1 s_1) = 1 \\ r_i s_i \le B_i}} 
    \frac{\gamma_{r_1} \lambda_{s_1} \overline{\gamma_{r_2}\lambda_{s_2}}}{r_1 r_2 s_1 s_2 q}
    \sum_{\substack{n_1, n_2 \sim N \\ n_1 \equiv n_2 \ (\textnormal{mod } qd) \\ (n_1, n_2 q d r_1 s_1) = 1 \\ (n_2, n_1 q d r_2 s_2) = 1 \\ (n_1 r_2 s_2; n_2) \in \mathscr{N} \\ |n_1 - n_2| \ge N/(\log x)^C}} 
    \alpha_{n_1} \overline{\alpha_{n_2}}&
    \\
    \times 
    \sum_{h \in \mathbb{Z}} e(h\omega)\, \Phi\left(\frac{h}{H}\right) 
    e\left(\frac{ah(n_1 - n_2) \overline{n_2 r_1 s_1 dq}}{n_1 r_2 s_2}\right)&
    \ll_{a,\varepsilon,C}
    \frac{N^2}{Qx^\varepsilon}.
\end{aligned}
\]

Let $\varepsilon > 0$ be small enough, $a \in \mathbb{Z} \setminus \{0\}$, $v, d_1, d_2 \in \mathbb{Z}_+$, $\theta := 7/32$, and $1 \ll M, K, N, L, H, R \ll x$ satisfy 
\begin{equation} 
\begin{gathered}    
    |avd_1d_2| \ll x^\varepsilon, \qquad NL \ll x^\varepsilon K, \qquad R \ll K \ll \min(x^{-3\varepsilon} MN, LN^2),
    \qquad 
    H \ll x^\varepsilon \frac{R}{M},
    \\
    K \ll x^{-25\varepsilon} \sqrt{M N R}, \qquad\quad 
    K^{3+\theta} N^{2-3\theta} \ll x^{-200\varepsilon} M^{2-2\theta} R^{2+\theta} L.
\end{gathered}
\end{equation}
Let $(u_k)_{K < k \le 4K}, (\beta_n)_{n \sim N}, (\lambda_\ell)_{\ell \sim L}$ be complex sequences such that $|u_k| \le \tau(k)$, $|\beta_n| \le 1$, $|\lambda_\ell| \le 1$, and
\[
    (k, vd_1d_2) > 1 \ \Rightarrow \ u_k = 0,
    \qquad\qquad 
    (n\ell, vd_1) > 1 \ \Rightarrow \ \beta_n \lambda_\ell = 0.
\]
Then for any smooth functions $\Phi(t)$, $\Psi(t)$ supported in $t \asymp 1$ with $\Phi^{(j)}, \Psi^{(j)}, \ll_j 1$, and any $\omega \in \mathbb{R}/\mathbb{Z}$ with $T_H(\omega) \ll x^\varepsilon$, one has
\begin{equation} 
\begin{aligned}
    \sum_{\substack{r \sim R \\ (r, avd_1 d_2) = 1}}
    \frac{M}{r} \Psi\left(\frac{r}{R}\right)
    \sum_{\substack{k,n,\ell \\ d_1 k \equiv d_2 n\ell \ (\textnormal{mod } r) \\ (d_1 k, d_2 n \ell) = 1}}
    u_k \beta_n \lambda_\ell 
    \sum_{h \in \mathbb{Z}} e(h\omega)\, \Phi\left(\frac{h}{H}\right) 
    e\left(\frac{-ha\overline{vd_1d_2k}}{r}\right)
    \\
    \ll_{\varepsilon} 
    x^{-10\varepsilon} \frac{KMNL}{R}.
\end{aligned}
\end{equation}

Let $a \in \mathbb{Z} \setminus \{0\}$, $A, \varepsilon > 0$, $x \ge 2$. Assume either:
    \begin{itemize} 
        \item[$(i)$.] $Q \le x^{5/8-\varepsilon}$, and $(\lambda_q)$ are triply-well-factorable weights of level $Q$, or
        \item[$(ii)$.] $Q \le x^{3/5-\varepsilon}$, and $(\lambda_q)$ are the upper-bound well-factorable  linear sieve weights of level $Q$.
    \end{itemize}
    (See 5.1 for part $(ii)$.) Then one has
    \begin{equation} 
        \sum_{\substack{q \le Q \\ (q, a) = 1}} 
        \lambda_q \left(\pi(x; q, a) - \frac{\pi(x)}{\varphi(q)}\right) \ll_{\varepsilon,A,a}
        \frac{x}{(\log x)^A}.
    \end{equation}

For any $\varepsilon, A > 0$ and $k \ge 1$, there exist $\delta, C > 0$ such that the following holds. Let $x \ge 2$ and $a_1, a_2 \in \mathbb{Z}\setminus \{0\}$ satisfy $(a_1, a_2) = 1$ and $|a_1a_2| \le x^\delta$. Then for any $y_1 \in [(\log x)^C, x^{1/C}]$, $y_2 \in [(\log x)^C, x]$, $Q \le x^{5/8 - \varepsilon}$, and $q_0 \in \mathbb{Z}_+$ with $q_0 \le x^\delta$, $(q_0, a_1a_2) = 1$, $P^+(q_0) \le y_2$, one has
\begin{equation} 
    \sum_{\substack{q \sim Q \\ P^+(q) \le y_2 \\ (q, a_1a_2) = 1}}
    \tau_k(q)
    \left\vert 
    \Psi(x, y_1; a_1\overline{a_2}, q_0q) - 
    \frac{\Psi_{q_0q}(x, y_1)}{\varphi(q_0q)} \right\vert 
    \ll_{\varepsilon,A,k}
    \frac{\Psi(x, y_1)}{(\log x)^A} \frac{\Psi(Q, y_2)}{\varphi(q_0)Q} e^{O_k(u_2)},
\end{equation}
where $u_2 := (\log x)/\log y_2$.
